(function($) {
    $.fn.SuperBox = function(options) {
        var superbox = $('<div class="superbox-show"></div>');
        
        var htmlAdd  = '';
        if(options.exibir_categorias == true){
            htmlAdd  = '<p>Categoria:<br /><select class="superbox-img-categoria" style="width:350px; font-size:14px; color: #000;   font-weight: normal;">'+options.categorias+'</select></p><br />';
        }
        var superboximg = $('<img src="" class="superbox-current-img">\n\
                                <div id="imgInfoBox" class="superbox-imageinfo inline-block"> \n\
                                    '+htmlAdd+'\n\
                                    <p>Título: <label style="color:#FF0000;">*</label><br /><input type="text" class="superbox-img-title input_login" value="" style="width:350px; font-size:15px;" maxlength="45"></p><br />\n\
                                    <span>\n\
                                        <p><label style="color:#FFF"><b>Descrição:</b></label> <label style="color:#FF0000;">*</label><br /> <textarea class="superbox-img-description input_login conta_caracteres" value="" row="7" style="padding:5px; width:350px; height:100px; font-size:13px;" maxlength="200" rel=".note_descricao"></textarea></p>\n\
                                        <div class="note note_descricao">Total de caracteres restantes --- </div>\n\
                                        <br />\n\
                                        <div class="note"><label style="color:#FF0000;">*</label> <i>Campos Obrigatórios</i></span>\n\
                                        <br />\n\
                                        <a href="javascript:void(0);" class="btn btn-primary btn-sm superbox-img-atualizar">Atualizar Alterações</a> \n\
                                        <a href="javascript:void(0);" class="btn btn-danger btn-sm superbox-img-excluir">Excluir</a></p>\n\
                                        <p class="aviso_result" style="color:white;"></p>\n\
                                    </span> \n\
                                </div>');

        
        
        var superboxclose = $('<div class="superbox-close txt-color-white"><i class="fa fa-times fa-lg"></i></div>');
        superbox.append(superboximg).append(superboxclose);
        var imgInfoBox = $(".superbox-imageinfo");
        return this.each(function() {
            $(".superbox-list").click(function() {
                $this = $(this);
                var currentimg = $this.find(".superbox-img"), 
                    imgData = currentimg.data("img"), 
                    imgDescription = currentimg.attr("alt") || "", 
                    imgTitle = currentimg.attr("title") || "";
                    imgId = currentimg.attr("rel") || "";
                    imgCategoria = currentimg.attr("parametro") || "";
                    pe = jQuery.data(document.body, "ac").p;
                    superboximg.attr("src", imgData);
                    
                
  

                $(".superbox-list").removeClass("active");
                $this.addClass("active");
                superboximg.find(".superbox-img-title").val(imgTitle);
                superboximg.find(".superbox-img-title").attr('name','title_'+imgId);
                
                superboximg.find(".superbox-img-description").val(imgDescription);
                superboximg.find(".superbox-img-description").attr('name','description_'+imgId);
                
                superboximg.find(".superbox-img-categoria").val(imgCategoria);
                superboximg.find(".superbox-img-categoria").attr('name','categoria_'+imgId);
                
                superboximg.find(".superbox-img-atualizar").attr('rel',imgId);
                superboximg.find(".superbox-img-excluir").attr('rel',imgId);
                superboximg.find(".superbox-img-excluir").attr('pach',imgData);
                
                if ($(".superbox-current-img").css("opacity") == 0) {
                    $(".superbox-current-img").animate({opacity: 1});
                }
                if ($(this).next().hasClass("superbox-show")) {
                    $(".superbox-list").removeClass("active");
                    superbox.toggle();
                } else {
                    superbox.insertAfter(this).css("display", "block");
                    $this.addClass("active");
                }
                $("html, body").animate({scrollTop: superbox.position().top - currentimg.width()}, "medium");
                
                if(pe != ''){
                    if(pe < 3){
                        $('.superbox-img-excluir').remove();
                    }
                    if(pe < 2){
                        $('.superbox-img-atualizar').remove();
                        superboximg.find(".superbox-img-title").attr('readonly','readonly');
                        superboximg.find(".superbox-img-description").attr('readonly','readonly');
                        $('.note_descricao').remove();
                    }
                }else{
                    $('.superbox-img-excluir').remove();
                    $('.superbox-img-atualizar').remove();
                    superboximg.find(".superbox-img-title").attr('readonly','readonly');
                    superboximg.find(".superbox-img-description").attr('readonly','readonly');
                    $('.note_descricao').remove();
                }
                
            });
            $(".superbox").on("click", ".superbox-close", function() {
                $(".superbox-list").removeClass("active");
                $(".superbox-current-img").animate({opacity: 0}, 200, function() {
                    $(".superbox-show").slideUp();
                });
            });
            
           
        });
    }
})(jQuery);


/**
 * <img src="" class="superbox-current-img">
 * <div id="imgInfoBox" class="superbox-imageinfo inline-block"> 
 * <h1>Image Title</h1>
 * <span>
 * <p><em>http://imagelink.com/thisimage.jpg</em></p>
 * <p class="superbox-img-description">Image description</p>
 * <p><a href="javascript:void(0);" class="btn btn-primary btn-sm">
 * Edit Image</a> 
 * <a href="javascript:void(0);" class="btn btn-danger btn-sm">Delete</a>
 * </p>
 * </span> 
 * </div>
 */